  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*100,80+Math.cos(t*0.35)*50,0.075,2.2,1.0],
    [320+Math.cos(t*0.45)*100,160+Math.sin(t*0.6)*50,0.09,1.8,0.8],
    [240+Math.sin(t*0.28+2)*140,120+Math.cos(t*0.45+1)*90,0.055,2.5,1.2],
    [100+Math.cos(t*0.7+1)*90,190+Math.sin(t*0.55+3)*70,0.11,1.4,0.9],
    [370+Math.sin(t*0.38+4)*80,55+Math.cos(t*0.8+2)*65,0.065,2.8,1.1],
    [240+Math.cos(t*0.32+5)*120,210+Math.sin(t*0.5)*80,0.085,2.0,0.7],
