  ];
  let act=0,inh=0,cross=0,wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp)*w;inh+=Math.sin(d*f*0.7+t*sp*0.55+1.8)*w;
    cross+=Math.sin(d*f*1.3-t*sp*0.8+3)*w*0.5;wS+=w;
  }
  act/=wS;inh/=wS;cross/=wS;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95)+Math.sin(sx*0.045+sy*0.01-t*0.6))/3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t)+Math.sin(dist*0.06-ang*2-t*1.8)*0.6)/2.6;
  const cx2=180+Math.sin(t*0.2)*60,cy2=100+Math.cos(t*0.15)*40;
  const d2=Math.sqrt((sx-cx2)**2+(sy-cy2)**2),a2=Math.atan2(sy-cy2,sx-cx2);
