  const raw=act-inh*0.65+bg*0.25+spiral*0.35+cross*0.2+sp2+cell*0.4+fd*0.12;
  const reaction=Math.tanh(raw*2);
  const glow=Math.exp(-Math.abs(reaction)*1.5)*0.25;
  const eB=Math.abs(reaction)>0.6?1+(Math.abs(reaction)-0.6)*0.5:1;
  const v=reaction*0.5+0.5+glow*0.08;
  const pal=[[5,10,48],[10,38,78],[16,72,108],[22,120,125],[38,158,135],[95,185,125],[165,200,85],[210,178,55],[215,135,50],[195,82,58],[158,48,68],[105,28,62],[58,16,52],[25,10,42],[5,10,48]];
  const idx=Math.max(0,Math.min(v*(pal.length-1),pal.length-1.001));
