    Math.min(255,Math.max(0,(c0[1]+(c1[1]-c0[1])*sf)*lum*eB))|0,
    Math.min(255,Math.max(0,(c0[2]+(c1[2]-c0[2])*sf)*lum*eB))|0
  ];
}
